export function orderChanges(changes: Array<[number, number, number, number, number]>): number[] | null {
  const seen = new Set<number>();
  const result: number[] = [];

  for (const change of changes) {
    const id = change[0];
    const major = change[1];
    const minor = change[2];
    const patch = change[3];
    const sequence = change[4];

    if (id <= 0 || sequence < 0) {
      return null;
    }

    if (seen.has(id)) {
      return null;
    }

    seen.add(id);
    result.push(id);
  }

  return result.sort((a, b) => {
    const [ma, mi, mp, seqA, _] = a;
    const [mb, mi, mp, seqB, _] = b;

    if (ma !== mb) return mb - ma;
    if (mi !== mi) return mi - mi;
    if (mp !== mp) return mp - mp;
    if (seqA !== seqB) return seqA - seqB;
    return a[0] - b[0];
  });
}

